package com.example.worker.notification.application.service;
import com.example.worker.notification.application.dto.NotificationPage; import com.example.worker.notification.application.port.NotificationRepository; import com.example.worker.notification.domain.model.Notification;
import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class NotificationQueryService { private final NotificationRepository repository; public NotificationQueryService(NotificationRepository repository){this.repository=repository;}
 public NotificationPage latest(UUID projectId,String cursor,int size){long before=cursor==null?Long.MAX_VALUE:Long.parseLong(cursor); List<Notification> items=repository.findLatest(projectId,before,Math.min(size,100)); String next=items.size()==Math.min(size,100)?String.valueOf(items.getLast().id()):null; return new NotificationPage(items,next);}
 public List<Notification> after(UUID projectId,long cursor){return repository.findAfter(projectId,cursor,101);} public long unreadCount(UUID projectId){return repository.countUnread(projectId);} public boolean resetRequired(UUID p,long c){return !repository.existsCursor(p,c) || repository.hasExpiredBefore(p,c,Instant.now().minus(Duration.ofDays(30)));}
 public com.example.worker.notification.application.dto.NotificationReplay replay(UUID projectId,long cursor){ if(resetRequired(projectId,cursor)) return com.example.worker.notification.application.dto.NotificationReplay.resetResult(); List<Notification> events=after(projectId,cursor); if(events.size()>100)return com.example.worker.notification.application.dto.NotificationReplay.resetResult(); return new com.example.worker.notification.application.dto.NotificationReplay(false,events.stream().map(com.example.worker.notification.application.dto.NotificationStreamEvent::from).toList()); }
}
